import{_ as t,c as l,j as e,a as n,o as r}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"你是什么时候突然发现你自己炒股悟道的？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/耐心等待.md","filePath":"stock/交易认知/耐心等待.md"}'),o={name:"stock/交易认知/耐心等待.md"};function s(c,a,p,d,i,_){return r(),l("div",null,a[0]||(a[0]=[e("h1",{id:"你是什么时候突然发现你自己炒股悟道的",tabindex:"-1"},[n("你是什么时候突然发现你自己炒股悟道的？ "),e("a",{class:"header-anchor",href:"#你是什么时候突然发现你自己炒股悟道的","aria-label":'Permalink to "你是什么时候突然发现你自己炒股悟道的？"'},"​")],-1),e("p",null,"先给结论，大概专职做股票五六年以后的某一天，或者说那一段时间，脑子里产生了一种念头，市场每天涨涨跌跌，看似机会很多，但能够抓的住的其实是很少的。只有某一种情况出现的时候，把单子做进去，心里是坦然的，是踏实的。在这样的情况下，后面的走势大多数跟我想的差不多。如果不是在这样的条件下去开仓，心里觉得怎么都不对，后面的发展多数也是让我亏钱收场。",-1),e("p",null,"从那以后我就没有随便买股票，不看股评也不听别人怎么说。自己觉得不合适的时候就一直空仓观望，直到某一天觉得合适了，然后才考虑进场的问题。这样的坚持也让我躲过了这两年的股市的低迷。个人觉得接下来A股要进行相当长时间的震荡，就等着震荡结束，最后收敛，看往哪个方向去再说。",-1),e("p",null,"这个可能跟我每天做期货日内波段也有关系，因为周期短，每天都要进行复盘。慢慢发现做短线在一天之内不被套住的时候也是很少的，但是只要耐心等最多一两天，总有一次让吃住一个波段的机会，因为这个时候大家都等得不耐烦了，就一起王某个方向发力，自然就有盈利的空间了。",-1),e("p",null,"跟大多数进入这个市场的朋友一样，印象中至少在前面五六年，到处寻找盈利的方法，读过三四十本相关的书，看过很多视频，论坛，但是也一直在亏损的泥潭中挣扎。到后来就是本回答前面说的，慢慢的就不乱做了，非要等到自己觉得把握比较大的时候才考虑进场。只要耐心，基本都能卡在行情启动的附近。",-1),e("p",null,"思路也可以在这里跟大家说一下，从k线图上很容易看出来，市场有一个基本的规律，就是大幅波动之后就要进入盘整震荡的阶段，震荡结束之后必然又要大幅波动，就这样不停的循环。我的做法就是专门等待在震荡区间结束的位置，试图卡在接下来一波行情的启动点附近，其他的机会都放弃。无论股票期货都是这样做的，只是周期不同。",-1),e("p",null,"明白道理，能够驾轻就熟的去运用，那还有很长的距离，就是要在实践中慢慢去体会去总结，后来就会变得越来越熟练。比如，考虑整个市场，相关行业板块的分为，隔夜外盘的情况，期货市场当日的强弱等，如果这些因素都配合，开仓的成功率就会高很多。",-1)]))}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
